          return JSON.parse(document.getElementById('chart-data').textContent);
        }

        function constrain(to, min, max) {
          return Math.min(Math.max(to, min), max);
        }

        function interpolateColor(to) {
          const colors = ['#ff69b4', '#66d9ef', '#8bc34a', '#f7dc6f', '#9c27b0'];
          return colors[Math.floor((to / 100) * colors.length)];
